style.css:
/* --- YouTube Angel Theme by Starpasta (Ultra Edition 4.1) --- */
@-moz-document domain("youtube.com") {
/* --- Fullscreen Background Image --- */
  body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-image: url("/*[[bgimage]]*/") !important;
    background-size: 35% auto !important;
    background-repeat: no-repeat !important;
    background-position: center top !important;
    background-attachment: fixed !important;
    z-index: -9999 !important;
    pointer-events: none;
    filter: brightness(1.05) contrast(1.05) saturate(1.12) blur(0.6px);
  }

  /* --- Replace YouTube Logo with Custom GIF --- */
  #logo-icon {
  display: none !important;
}

  ytd-topbar-logo-renderer {
  display: none !important;
}

  /* --- Reset YouTube's Default BG --- */
  ytd-app {
    background: transparent !important;
  }

  /* --- General Font & Text Styling --- */
  body {
    background-color: transparent !important;
    color: #fff !important;
    font-family: "/*[[font]]*/", sans-serif !important;
    transition: all 0.3s ease !important;
  }

  /* --- Header Blur Fix --- */
  #masthead-container, ytd-masthead {
    background: rgba(0, 0, 0, 0.55) !important;
    backdrop-filter: blur(14px) !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1) !important;
    box-shadow: 0 2px 12px rgba(255, 255, 255, 0.08) !important;
  }

  /* --- Content Glow Containers --- */
  ytd-rich-grid-media,
  ytd-video-renderer,
  ytd-thumbnail,
  ytd-rich-item-renderer {
    background: rgba(255, 255, 255, 0.04) !important;
    backdrop-filter: blur(6px);
    border-radius: 16px !important;
    box-shadow: 0 6px 24px rgba(255, 255, 255, 0.1);
    transition: all 0.3s ease;
  }

  ytd-rich-grid-media:hover,
  ytd-video-renderer:hover {
    transform: scale(1.035);
    box-shadow: 0 0 22px rgba(255, 255, 255, 0.3);
  }

  /* --- Sidebar Glow Hover --- */
  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background-color: rgba(255, 255, 255, 0.07) !important;
  }

  /* --- Search Bar Styling --- */
  #search-input {
    border-radius: 18px !important;
    background: rgba(255, 255, 255, 0.06) !important;
    box-shadow: inset 0 0 4px rgba(255, 255, 255, 0.1), 0 0 10px rgba(255, 255, 255, 0.07) !important;
  }

  /* --- Buttons & Icon Hover Glow --- */
  tp-yt-paper-button,
  yt-icon-button,
  a.yt-simple-endpoint {
    transition: box-shadow 0.3s ease;
  }

  tp-yt-paper-button:hover,
  yt-icon-button:hover,
  a.yt-simple-endpoint:hover {
    box-shadow: 0 0 12px rgba(255, 180, 255, 0.3);
  }

  /* --- Scrollbar Styling --- */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: rgba(255, 255, 255, 0.03);
  }
  ::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.2);
    border-radius: 10px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: rgba(255, 255, 255, 0.3);
  }

  /* --- Active Tabs --- */
  paper-tab.iron-selected {
    color: #ffccff !important;
    font-weight: bold;
  }

  /* --- Glow Focus Effects --- */
  input:focus,
  textarea:focus,
  select:focus {
    outline: none;
    border: 1px solid rgba(255, 200, 255, 0.4);
    box-shadow: 0 0 10px rgba(255, 200, 255, 0.4);
  }

  /* --- Transparent Section Paddings --- */
  ytd-section-list-renderer {
    border-top: 1px solid rgba(255, 255, 255, 0.05);
    padding-top: 10px;
    margin-top: 10px;
  }

  /* --- Mobile Hover Fix --- */
  @media (max-width: 768px) {
    ytd-rich-grid-media:hover,
    ytd-video-renderer:hover {
      transform: none !important;
      box-shadow: none !important;
    }
  }

  /* --- Transition Boost Everywhere --- */
  ytd-app *,
  ytd-page-manager * {
    transition: background-color 0.3s ease, color 0.3s ease, border-color 0.3s ease;
  }
}
